package com.farika.soundflow;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.io.*;import java.lang.reflect.*;import java.util.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,application=android.app.Application.class)
public class FlowUiTest {
 List<View> all(View root){List<View> views=new ArrayList<>();views.add(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)views.addAll(all(((ViewGroup)root).getChildAt(i)));return views;}
 View field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return (View)f.get(object);}
 @Test public void emptyMainHidesMiniPlayerAndLibraryHasSingleDownloadIcon()throws Exception{RuntimeEnvironment.getApplication().getSharedPreferences("profile",0).edit().clear().commit();org.robolectric.android.controller.ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity main=controller.get();assertEquals(View.GONE,field(main,"mini").getVisibility());for(View v:all(main.getWindow().getDecorView()))if(v instanceof TextView&&"Медиатека".contentEquals(((TextView)v).getText())){((View)v.getParent()).performClick();break;}int icons=0;for(View v:all(main.getWindow().getDecorView()))if("Загрузки".contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))icons++;assertEquals(1,icons);controller.pause().stop().destroy();}
 @Test public void settingsHasNoBackgroundMusicMentionAndHasFiveVerticalFaders(){org.robolectric.android.controller.ActivityController<AppSettingsActivity> controller=Robolectric.buildActivity(AppSettingsActivity.class).setup();int count=0;boolean wifi=false;for(View v:all(controller.get().getWindow().getDecorView())){if(v instanceof VerticalFader)count++;if(v instanceof TextView){String text=((TextView)v).getText().toString();assertFalse(text.contains("Музыка в фоне"));assertFalse(text.contains("Wi-Fi /"));if(text.equals("Только Wi-Fi"))wifi=true;}}assertTrue(wifi);assertEquals(5,count);controller.pause().stop().destroy();}
 @Test public void initialPresetDoesNotEnableDisabledEqualizer(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();a.getSharedPreferences("equalizer",0).edit().putInt("preset",1).putBoolean("enabled",false).commit();View panel=EqualizerPanel.create(a);a.setContentView(panel);panel.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.AT_MOST));panel.layout(0,0,400,panel.getMeasuredHeight());Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(a.getSharedPreferences("equalizer",0).getBoolean("enabled",false));a.finish();}
 @Test public void changingPresetUpdatesStoredGains(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();a.getSharedPreferences("equalizer",0).edit().putInt("preset",-1).commit();View panel=EqualizerPanel.create(a);a.setContentView(panel);panel.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.AT_MOST));panel.layout(0,0,400,panel.getMeasuredHeight());Shadows.shadowOf(Looper.getMainLooper()).idle();Spinner spinner=null;for(View v:all(panel))if(v instanceof Spinner)spinner=(Spinner)v;assertNotNull(spinner);spinner.setSelection(2);panel.layout(0,0,400,panel.getMeasuredHeight());Shadows.shadowOf(Looper.getMainLooper()).idle();AudioEqualizer eq=new AudioEqualizer(a);assertTrue(eq.enabled());assertEquals(600,eq.gain(eq.frequencies()[0]));a.finish();}
}
